import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.listing.*; import ghidra.program.model.symbol.*;
public class Dispatcher extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);long[] xs={0x00425800L,0x00426170L,0x004264c0L};for(long x:xs){Function f=getFunctionAt(toAddr(x));println("=== "+toAddr(x)+" "+f.getName()+" ===");DecompileResults z=d.decompileFunction(f,600,monitor);String c=z.getDecompiledFunction().getC();for(String l:c.split("\n"))println(l);}d.dispose();}}
